import { useState, useEffect, useLayoutEffect, useMemo, useRef, useCallback } from "react";
import { __, sprintf } from "@wordpress/i18n";
import { Fancybox } from "@fancyapps/ui";
import VideoThumbnail from "react-video-thumbnail";
// Scoped to this plugin's own lightbox; see tools/scope-fancybox-css.js.
import "../../fancybox-scoped.css";

import Style from "./Style";
import VideoGalleryFilter from "./VideoGalleryFilter";
import InlinePlayer, { inlineSource } from "./InlinePlayer";
import {
  albumClasses,
  captionText,
  facebookEmbedUrl,
  getVimeoId,
  getYoutubeId,
  getYoutubeThumbnails,
  isFacebookVideo,
  isYoutubeShort,
  plyrOptions,
  videoProviderId,
  safeLightboxSrc,
  slideAlt,
} from "../../utils/functions";
import { prefix } from "../../utils/data";
import { watchPlay } from "../../utils/playTracking";
import { itemDetails } from "../../utils/details";
import fancyboxDragGuard from "../../utils/fancyboxDragGuard";
import { getLightboxMount } from "../../utils/lightboxHost";
import Plyr from "plyr";
import { sanitizeHTML } from "../../../../../../bpl-tools/utils/common";

fancyboxDragGuard();

/*
 * Our own lightbox attribute, never `data-fancybox`. That one is the default
 * selector every Fancybox copy (any other plugin's, any version) auto-binds on
 * the document, so sharing it made two copies fight over one click: the
 * lightbox opened twice, was blocked by the other copy, or never opened, and
 * the other plugin's copy also took over our items. Keep in sync with
 * `render.php`.
 */
const LIGHTBOX_ATTR = "data-vgb-lightbox";

/**
 * Turn the <video> in a lightbox slide into a Plyr player.
 *
 * `slide.el` is the slide's root DOM element -- confirmed by Fancybox's own
 * source, which finds a slide's video the same way (`slide.el.querySelector
 * ("video")`). The earlier code called a `getContentEl()` method that does
 * not exist on a CarouselSlide at all (the `?.()` optional call silently
 * no-op'd on `undefined`), and before that, `contentEl` turned out to be the
 * bare `<video>`/`<iframe>` element itself, not a container -- querying
 * *its own* descendants for "video" could never match the element itself.
 */
const initPlyr = (slide) => {
  const videoEls = slide?.el?.querySelectorAll(
    "video, .fancybox__html5video",
  );

  if (!videoEls?.length) {
    return;
  }

  videoEls.forEach((el) => {
    if (!el.plyr) {
      // Our own copy of Plyr, never a global another plugin may have loaded
      // under the same name. In the isolated lightbox the icon sprite lives in
      // that root (see lightboxHost.js), so Plyr must not fetch its own.
      const isolated = el.getRootNode() instanceof ShadowRoot;
      new Plyr(el, isolated ? { ...plyrOptions, loadSprite: false } : plyrOptions);
    }
  });
};

/**
 * Pushes a GA4-shaped `video_start` event to `window.dataLayer` for the slide
 * that just became active in the lightbox.
 *
 * Fired from Fancybox's `Carousel.contentReady` event rather than only when
 * a gallery item is first clicked, so browsing to the next video with the
 * lightbox's own Next/Prev controls -- not just the initial open -- counts
 * as a play too. `dataLayer.push` is a no-op when nothing is reading it (no
 * GTM/GA4 on the site), so this is safe to call unconditionally once the
 * option is on.
 */
const pushVideoEvent = (slide, eventName = "video_start", extra = {}) => {
  if (typeof window === "undefined") return;

  /*
   * `slide.src` is not always the real video URL by the time this reads it:
   * Fancybox rewrites a YouTube or Vimeo URL into its own player-embed URL
   * (full of its own query params), and a Facebook video's `src` is its
   * embed iframe URL (see `facebookEmbedUrl()`) -- both make for an
   * unreadable `video_url` in Analytics, and fail `videoProviderId()`'s
   * plain URL check. `videoUrl` (set on the item by `showLightbox()`) is the
   * real one; `triggerEl`'s `data-video-url` is the same thing for a slide
   * Fancybox opened on its own via `[data-vgb-lightbox]` DOM binding, which
   * never passes through `showLightbox()` at all.
   */
  const url =
    slide?.videoUrl || slide?.triggerEl?.dataset?.videoUrl || slide?.src || "";

  const params = {
    video_title: slide?.caption || "",
    video_provider: videoProviderId(url),
    video_url: url,
    ...extra,
  };

  window.dataLayer = window.dataLayer || [];
  window.dataLayer.push({ event: eventName, ...params });

  /*
   * A site with plain gtag.js (Site Kit, a pasted GA4 snippet) has no GTM
   * trigger listening for the dataLayer event above, so send the same event
   * straight to GA4 as well. `gtag` only exists when that snippet is loaded.
   */
  if (typeof window.gtag === "function") {
    window.gtag("event", eventName, params);
  }
};

/** The small picture for a video in the lightbox's thumbnail strip. */
const stripThumb = (item) => {
  if (item?.poster) return item.poster;
  const youtubeId = getYoutubeId(item?.video);
  return youtubeId ? `https://i.ytimg.com/vi/${youtubeId}/mqdefault.jpg` : "";
};

/**
 * Shared lightbox configuration.
 *
 * No `container`: the lightbox belongs to <body>, so it covers the screen. It
 * used to be mounted inside the gallery itself, which put it underneath any
 * themed ancestor with `overflow: hidden`, a `transform`, or a stacking
 * context of its own -- and then it was clipped rather than covering anything.
 */
const fancyboxOptions = (id, { trackVideoEvents = false, isolated = false } = {}) => ({
  // Front end: mounted in a shadow root no other plugin's CSS can reach.
  ...(isolated ? { parentEl: () => getLightboxMount() } : {}),
  mainClass: `vidgalblkFancyBox ${id}-fancyBox`,
  /*
   * Group by our own attribute. Fancybox defaults to `data-fancybox`, which
   * every other plugin's copy of Fancybox auto-binds on the whole document, so
   * a shared attribute made two copies react to one click.
   */
  groupAttr: LIGHTBOX_ATTR,
  Toolbar: {
    display: {
      left: ["counter"],
      middle: [],
      right: ["share", "zoom", "slideshow", "fullscreen", "close"],
    },
  },
  Carousel: { infinite: false },
  Thumbs: { autoStart: true },
  contentClick: "toggleZoom",
  on: {
    // A video playing in place would keep playing under the lightbox; stop it.
    ready: () => {
      window.dispatchEvent(
        new CustomEvent("vidgalblkInlinePlay", { detail: "lightbox" }),
      );
    },
    /*
     * Not `done` -- that was never a real Fancybox v5 event, so the handler
     * silently never ran and Plyr was never actually initialized on a video
     * slide (default HTML5 controls masked this; nothing looked broken).
     * `Carousel.contentReady` is: "content is loaded on one of the slides" --
     * the correct point to both hand a freshly-loaded <video> to Plyr and
     * count a video as started.
     */
    /*
     * Three arguments, not two: the Fancybox API instance, then the
     * Carousel instance the event is prefixed from, then the event's own
     * argument -- here, the CarouselSlide. Easy to miss since most examples
     * only show a two-argument `(fancybox, slide)` handler for Fancybox's
     * own un-prefixed events (`close`, `ready`, ...), which carry no
     * Carousel instance in front.
     */
    "Carousel.contentReady": (fancybox, carousel, slide) => {
      initPlyr(slide);
      if (trackVideoEvents) {
        pushVideoEvent(slide);
        // `video_start` above means the video was opened; this is the real play.
        watchPlay(slide, {
      onPlay: () => pushVideoEvent(slide, "video_play"),
      onProgress: (mark) =>
        pushVideoEvent(slide, "video_watch_progress", { video_percent: mark }),
      onComplete: () =>
        pushVideoEvent(slide, "video_watch_complete", { video_percent: 100 }),
    });
      }
    },
  },
});

/**
 * Whether playing this video loads a third-party player -- what the consent
 * notice ("Ask before loading YouTube / Vimeo") is about. A file on the site
 * itself shares nothing with anyone, so it plays without the notice.
 */
const needsConsent = (video) =>
  !!(getYoutubeId(video) || getVimeoId(video) || isFacebookVideo(video));

/** Who a video's consent notice should say it is hosted by. */
const providerName = (video) => {
  if (getYoutubeId(video)) {
    return __("YouTube", "video-gallery-block");
  }

  if (getVimeoId(video)) {
    return __("Vimeo", "video-gallery-block");
  }

  if (isFacebookVideo(video)) {
    return __("Facebook", "video-gallery-block");
  }

  return __("its provider", "video-gallery-block");
};

/**
 * A thumbnail that steps down through the sources it could have.
 *
 * A poster the user set wins; then anything the server resolved (this is how a
 * Vimeo thumbnail arrives); then YouTube's own thumbnails, best first. Stepping
 * down on `error` is what stops a missing `maxresdefault.jpg` -- YouTube does
 * not have one for every video -- from showing as a broken image.
 */
const Thumbnail = ({ video, poster, thumb, thumbSet, thumbSizes, caption }) => {
  const candidates = useMemo(
    () =>
      [...new Set([poster, thumb, ...getYoutubeThumbnails(video)].filter(Boolean))],
    [poster, thumb, video],
  );

  const [index, setIndex] = useState(0);

  useEffect(() => setIndex(0), [candidates]);

  if (!candidates.length) {
    /*
     * Nothing to point at, so fall back to grabbing a frame out of the video
     * itself -- but only for a file the browser could actually read. Handing a
     * YouTube, Vimeo or Facebook page URL to a <video> element cannot work: it
     * fails on CORS and leaves nothing but errors in the console. Those tiles
     * get the empty-tile background from the stylesheet instead.
     */
    if (getYoutubeId(video) || getVimeoId(video) || isFacebookVideo(video)) {
      return null;
    }

    return <VideoThumbnail width={600} videoUrl={video} snapshotAtTime={2} />;
  }

  if (index >= candidates.length) {
    return null;
  }

  /*
   * The server's own cached picture, with its real size and (when there is
   * one) a smaller copy for narrow tiles. Only for that exact picture: if it
   * fails and the list steps down to another source, none of this applies.
   * The stylesheet gives the image width/height 100%, so the attributes only
   * tell the browser its shape; they never change the layout.
   */
  const sized = thumbSet && thumb && candidates[index] === thumb ? thumbSet : null;

  return (
    <figure className="galleryFigure">
      <img
        /*
         * With a srcset, no `src` is given: after mounting, React assigns
         * `img.src = <the prop>` once more, and that makes the browser fetch the
         * full-size file on top of the smaller copy it had already chosen. The
         * browser picks from `srcSet` on its own. (The server's markup keeps its
         * `src`, so a visitor without JavaScript is unaffected.)
         */
        {...(sized
          ? {
              width: sized.width,
              height: sized.height,
              ...(sized.srcset ? { srcSet: sized.srcset, sizes: thumbSizes } : {}),
            }
          : {})}
        loading="lazy"
        decoding="async"
        src={sized?.srcset ? undefined : candidates[index]}
        alt={captionText(caption)}
        onError={() => setIndex((current) => current + 1)}
        onLoad={(event) => {
          /*
           * A YouTube size that does not exist is not always an error: it can
           * come back as a 120x90 grey "no thumbnail" picture, which loads
           * fine and so never reached `onError` -- the tile showed that grey
           * box while the live page, whose server had stepped down to the
           * size that does exist, showed the real picture. No real size in
           * the list is that small, so treat it as missing.
           */
          const img = event.currentTarget;
          if (
            img.naturalWidth <= 120 &&
            /img\.youtube\.com|i\.ytimg\.com/.test(img.currentSrc || img.src) &&
            index < candidates.length - 1
          ) {
            setIndex((current) => current + 1);
          }
        }}
      />
    </figure>
  );
};

const VideoGallery = ({
  attributes,
  id,
  thumbs,
  // Frontend only: width/height/srcset of the cached thumbnails (index-aligned
  // with `thumbs`) and the `sizes` they are used with. Absent in the editor.
  thumbSets,
  thumbSizes,
  activeIndex,
  setActiveIndex,
  // Editor only: tiles that cannot be edited (a channel feed's) play on a
  // single click, since there is nothing for a click to select.
  previewOnClick = false,
  // Editor only: (index, prevIndex, nextIndex) => the tile's hover toolbar.
  renderTileTools,
}) => {
  const { videos, albums, options, filter, perPage, loadMoreLabel } = attributes;
  const [activeAlbum, setActiveAlbum] = useState("*");
  const [visibleCount, setVisibleCount] = useState(perPage > 0 ? perPage : Infinity);
  const galleryRef = useRef(null);

  /*
   * FLIP animation bookkeeping.
   *
   * `prevRectsRef` stores the bounding-client-rect of every `.galleryItem`
   * keyed by its `data-item-key`, captured just before the state change that
   * triggers a re-render. After React has committed the new DOM,
   * `useLayoutEffect` compares new positions against these snapshots and
   * plays the Invert → Play half of the FLIP.
   *
   * `isFirstRenderRef` prevents the FLIP effect from firing on the very first
   * mount (the initial page load should not animate).
   */
  const prevRectsRef = useRef(new Map());
  const isFirstRenderRef = useRef(true);
  const flipCleanupRef = useRef(null);

  const isEditor = !!setActiveIndex;

  /*
   * Consent gate: off by default (existing galleries keep embedding straight
   * away, exactly as before), and once a visitor accepts it stays accepted --
   * for every gallery already on the page too, via the event below, and for
   * their next visit, via localStorage. Read once at mount rather than on
   * every render, since localStorage is synchronous I/O.
   */
  const consentGateEnabled = !!options?.consentGate;

  // Real plays only -- an editor previewing the gallery while writing a page
  // should not show up in the site's own Analytics as a visitor watching it.
  const gaTrackingEnabled = !!options?.gaTracking && !isEditor;
  const [consentGranted, setConsentGranted] = useState(() => {
    try {
      return "1" === window.localStorage.getItem("vidgalblkVideoConsent");
    } catch (error) {
      return false;
    }
  });
  const [pendingIndex, setPendingIndex] = useState(null);

  /*
   * "Play in place": a video plays inside its own tile instead of the
   * lightbox. One at a time -- starting one stops the one playing, in this
   * gallery or any other on the page.
   */
  const playInline = "inline" === options?.playMode;
  const [playingIndex, setPlayingIndex] = useState(null);

  useEffect(() => {
    const onOtherPlay = (event) => {
      if (event.detail !== id) setPlayingIndex(null);
    };
    window.addEventListener("vidgalblkInlinePlay", onOtherPlay);
    return () => window.removeEventListener("vidgalblkInlinePlay", onOtherPlay);
  }, [id]);

  // Another album, or switching back to the lightbox, stops it.
  useEffect(() => setPlayingIndex(null), [activeAlbum, playInline]);

  const startInline = (index) => {
    setPlayingIndex(index);
    window.dispatchEvent(new CustomEvent("vidgalblkInlinePlay", { detail: id }));
  };

  useEffect(() => {
    if (!consentGateEnabled || consentGranted) {
      return;
    }

    const onConsentGranted = () => setConsentGranted(true);
    window.addEventListener("vidgalblkConsentGranted", onConsentGranted);

    return () =>
      window.removeEventListener("vidgalblkConsentGranted", onConsentGranted);
  }, [consentGateEnabled, consentGranted]);

  /*
   * Which videos are on screen.
   *
   * Filtering happens here rather than by hiding items with CSS, which is what
   * Isotope used to do. Two things fall out of that: the lightbox now cycles
   * only the videos the visitor can actually see, and filtering no longer needs
   * jQuery and Isotope to be present and working -- it used to fail silently
   * when they were not, which is a common outcome on sites that defer or
   * dequeue jQuery.
   *
   * The original index is carried along because the editor needs it to know
   * which item is being edited.
   */
  const visibleVideos = useMemo(() => {
    let list = (Array.isArray(videos) ? videos : [])
      .map((item, index) => ({ item, index }))
      // An entry with neither a video nor a poster has nothing to show and
      // nowhere to go. The editor keeps it -- that is a row someone is still
      // filling in -- but a visitor should not be given a dead tile, and
      // render.php leaves it out of the server markup for the same reason.
      .filter(({ item }) => item && (isEditor || item.video || item.poster));

    /*
     * Shorts, included, excluded, or kept as the only videos: an editorial
     * choice the gallery owner makes once, applied here so the editor's
     * preview matches what render.php already did for the front end -- the
     * front end's own `videos` attribute has already been filtered to this by
     * the time it reaches this component, so this is a no-op there and only
     * does real work in the editor's live preview.
     */
    const shortsFilter = options?.shortsFilter;
    // A YouTube feed applies this itself (see includes/youtube-feed.php): its
    // links are plain watch URLs, so judging them by the link would drop every
    // video from a playlist set to "Only Shorts".
    const isFeed = !!attributes?.feed?.enabled;
    if (!isFeed && ("hide" === shortsFilter || "only" === shortsFilter)) {
      const wantShorts = "only" === shortsFilter;
      list = list.filter(
        ({ item }) => isYoutubeShort(item.video) === wantShorts,
      );
    }

    /*
     * Same reasoning as the Shorts filter just above: reordered here only so
     * the editor's live preview matches what render.php already did for the
     * front end, whose `videos` attribute arrives pre-sorted. A video from
     * before this option existed has no `dateAdded` and sorts as the oldest
     * possible entry, same as the PHP side.
     */
    const sortOrder = options?.sortOrder;
    if ("newest" === sortOrder || "oldest" === sortOrder) {
      list = [...list].sort((a, b) => {
        const aDate = a.item?.dateAdded || 0;
        const bDate = b.item?.dateAdded || 0;
        return "newest" === sortOrder ? bDate - aDate : aDate - bDate;
      });
    }

    if ("*" === activeAlbum) {
      return list;
    }

    return list.filter(({ item }) =>
      (Array.isArray(item?.albs) ? item.albs : []).includes(activeAlbum),
    );
  }, [videos, activeAlbum, isEditor, options?.shortsFilter, options?.sortOrder, attributes?.feed?.enabled]);

  // An album that has been renamed or deleted must not leave the gallery stuck
  // on a filter that now matches nothing.
  useEffect(() => {
    if ("*" !== activeAlbum && !(albums || []).includes(activeAlbum)) {
      setActiveAlbum("*");
    }
  }, [albums, activeAlbum]);

  /*
   * FLIP-aware album change.
   *
   * Before the state change that causes React to re-render (and therefore
   * unmount / re-order items), we snapshot every current `.galleryItem`'s
   * position. The `useLayoutEffect` below picks those snapshots up after
   * the DOM has been committed but before the browser paints, and applies
   * the inverse transform so items appear to slide from their old position
   * to their new one — exactly the way Isotope did it.
   */
  const changeAlbum = useCallback((album) => {
    const container = galleryRef.current;
    if (container) {
      // Cancel any in-progress FLIP before starting a new one.
      if (flipCleanupRef.current) {
        flipCleanupRef.current();
        flipCleanupRef.current = null;
      }

      const rects = new Map();
      const containerRect = container.getBoundingClientRect();
      container.querySelectorAll(".galleryItem[data-item-key]").forEach((el) => {
        rects.set(el.dataset.itemKey, {
          left: el.getBoundingClientRect().left - containerRect.left,
          top: el.getBoundingClientRect().top - containerRect.top,
          width: el.getBoundingClientRect().width,
          height: el.getBoundingClientRect().height,
        });
      });
      prevRectsRef.current = rects;
    }
    setActiveAlbum(album);
  }, []);

  /*
   * FLIP layout animation — runs after React commits the DOM for a filter
   * or pagination change, before the browser paints.
   *
   * Three kinds of item:
   * 1. **Staying** — existed before AND after: FLIP-slide from old position.
   * 2. **Entering** — new in this render: fade-in + scale-up.
   * 3. **Leaving** — was in the previous render, gone now: a ghost DOM
   *    clone is absolutely positioned at the old location and fades out +
   *    scales down, then removed after the transition.
   *
   * Transition duration matches the old Isotope `transitionDuration: 0.5s`
   * and stagger matches `stagger: 30`.
   */
  useLayoutEffect(() => {
    // Skip the very first mount — the page load should not animate.
    if (isFirstRenderRef.current) {
      isFirstRenderRef.current = false;
      return;
    }

    const prevRects = prevRectsRef.current;
    if (!prevRects.size || !galleryRef.current) return;

    const container = galleryRef.current;
    const containerRect = container.getBoundingClientRect();
    const items = container.querySelectorAll(".galleryItem[data-item-key]");
    const currentKeys = new Set();
    const ghostEls = [];
    const timers = [];

    // ── 1. Staying + Entering items ──────────────────────────────────
    items.forEach((el, visualIndex) => {
      const key = el.dataset.itemKey;
      currentKeys.add(key);
      const prevData = prevRects.get(key);
      const newRect = el.getBoundingClientRect();

      if (prevData) {
        // FLIP slide: item existed before → animate from old position.
        const dx = prevData.left - (newRect.left - containerRect.left);
        const dy = prevData.top - (newRect.top - containerRect.top);

        if (Math.abs(dx) > 1 || Math.abs(dy) > 1) {
          el.style.transform = `translate(${dx}px, ${dy}px)`;
          el.style.transition = "none";
          // Force a reflow so the browser registers the "from" position.
          el.getBoundingClientRect(); // eslint-disable-line no-unused-expressions
          el.style.transition = "transform 0.5s ease-in-out, opacity 0.5s ease-in-out";
          el.style.transform = "";
        }
      } else {
        // New item → fade-in + scale-up, staggered.
        const delay = visualIndex * 30;
        el.style.opacity = "0";
        el.style.transform = "scale(0.001)";
        el.style.transition = "none";
        el.getBoundingClientRect(); // eslint-disable-line no-unused-expressions
        el.style.transition =
          `transform 0.5s ease-in-out ${delay}ms, opacity 0.5s ease-in-out ${delay}ms`;
        el.style.opacity = "1";
        el.style.transform = "scale(1)";
      }
    });

    // ── 2. Leaving items (ghost clones) ──────────────────────────────
    prevRects.forEach((data, key) => {
      if (currentKeys.has(key)) return; // Still present — already handled.

      const ghost = document.createElement("div");
      ghost.className = "galleryItem";
      ghost.setAttribute("aria-hidden", "true");
      Object.assign(ghost.style, {
        position: "absolute",
        left: `${data.left}px`,
        top: `${data.top}px`,
        width: `${data.width}px`,
        height: `${data.height}px`,
        opacity: "1",
        transform: "scale(1)",
        pointerEvents: "none",
        zIndex: "0",
        transition: "none",
      });
      container.appendChild(ghost);
      ghostEls.push(ghost);

      ghost.getBoundingClientRect(); // reflow
      ghost.style.transition = "transform 0.4s ease-in-out, opacity 0.4s ease-in-out";
      ghost.style.opacity = "0";
      ghost.style.transform = "scale(0.001)";
    });

    // ── 3. Cleanup ───────────────────────────────────────────────────
    const cleanupTimer = setTimeout(() => {
      items.forEach((el) => {
        el.style.transition = "";
        el.style.transform = "";
        el.style.opacity = "";
      });
      ghostEls.forEach((g) => g.remove());
      flipCleanupRef.current = null;
    }, 800);
    timers.push(cleanupTimer);

    flipCleanupRef.current = () => {
      timers.forEach(clearTimeout);
      items.forEach((el) => {
        el.style.transition = "";
        el.style.transform = "";
        el.style.opacity = "";
      });
      ghostEls.forEach((g) => g.remove());
    };

    prevRectsRef.current = new Map();

    return () => {
      timers.forEach(clearTimeout);
      ghostEls.forEach((g) => g.remove());
    };
  }, [activeAlbum, visibleCount]);

  /*
   * Switching albums re-starts pagination at the first page. Without this, a
   * visitor who had clicked "Load More" down to 30 revealed videos, then
   * filtered to an album with only 4, would find every one of those 4 already
   * revealed and no "Load More" button -- correct, but confusing the first
   * time it happens -- and switching to a third album would carry that same
   * arbitrary count into a set of videos it was never chosen for.
   */
  useEffect(() => {
    setVisibleCount(perPage > 0 ? perPage : Infinity);
  }, [activeAlbum, perPage]);

  const revealedVideos =
    perPage > 0 ? visibleVideos.slice(0, visibleCount) : visibleVideos;
  const hasMore = revealedVideos.length < visibleVideos.length;

  // Lightbox, front end only -- in the editor it is opened imperatively below
  // so that clicking a thumbnail also selects that video for editing.
  useEffect(() => {
    if (isEditor || !galleryRef.current) return;

    const container = galleryRef.current;
    Fancybox.bind(
      container,
      `[${LIGHTBOX_ATTR}]`,
      fancyboxOptions(id, { trackVideoEvents: gaTrackingEnabled, isolated: true }),
    );

    return () => {
      /*
       * `unbind`, not `destroy`. `Fancybox.destroy()` is static and tears down
       * every instance on the page, so a second gallery unmounting used to
       * break the first one -- and any other plugin using Fancybox with it.
       */
      Fancybox.unbind(container);
      Fancybox.close();
    };
  }, [id, isEditor, gaTrackingEnabled]);

  // The same Analytics events as the lightbox sends, for a video played in place.
  useEffect(() => {
    if (!gaTrackingEnabled || null === playingIndex) return;
    const item = videos?.[playingIndex];
    const el = galleryRef.current?.querySelector(".vgbInlinePlaying");
    if (!item || !el) return;

    const slide = { el, videoUrl: item.video, caption: captionText(item.caption) };
    pushVideoEvent(slide);
    watchPlay(slide, {
      onPlay: () => pushVideoEvent(slide, "video_play"),
      onProgress: (mark) =>
        pushVideoEvent(slide, "video_watch_progress", { video_percent: mark }),
      onComplete: () =>
        pushVideoEvent(slide, "video_watch_complete", { video_percent: 100 }),
    });
  }, [playingIndex, gaTrackingEnabled]);

  /*
   * Opens the lightbox at a given video's original index, in the editor and
   * on the front end alike. The editor shows every video regardless of
   * filters (that is a row someone may still be editing), so it groups from
   * the raw `videos` array; the front end groups from `revealedVideos` so the
   * lightbox contains exactly the tiles a visitor can see and cycle through,
   * matching what Fancybox's own DOM auto-binding would have grouped.
   */
  const showLightbox = (index) => {
    if (isEditor) {
      setActiveIndex(index);
    }

    const group = isEditor
      ? videos.map((item, i) => ({ item, index: i }))
      : revealedVideos;
    const startIndex = Math.max(
      0,
      group.findIndex(({ index: i }) => i === index),
    );

    Fancybox.show(
      group.map(({ item }) => {
        const rawSrc = item.video || item.poster;
        const facebook = isFacebookVideo(rawSrc);

        return {
          // Facebook's embed needs its own iframe URL as `src` (see
          // `facebookEmbedUrl()`), but `videoUrl` keeps the real, clean URL
          // around for GA4 tracking below -- an embed URL full of query
          // params makes for an unreadable `video_url` in Analytics reports,
          // and would also fail the plain `isFacebookVideo()` check there.
          src: facebook ? facebookEmbedUrl(rawSrc) : safeLightboxSrc(rawSrc),
          alt: slideAlt(item.caption),
          type: facebook ? "iframe" : undefined,
          videoUrl: rawSrc,
          /*
           * `thumbSrc` is the name Fancybox 6 counts when it decides whether
           * to show the thumbnail strip at all; with only `thumb` (its older
           * name) the strip never appeared here -- in the editor preview, or
           * on the page after the consent gate -- while the page's own
           * DOM-bound lightbox, which reads the tile images, had one.
           */
          // `mqdefault` (320x180) exists for every YouTube video, unlike
          // maxres, which would show YouTube's grey placeholder here.
          thumbSrc: stripThumb(item),
          thumb: stripThumb(item),
          caption: sanitizeHTML(item.caption || ""),
        };
      }),
      {
        startIndex,
        ...fancyboxOptions(id, { trackVideoEvents: gaTrackingEnabled, isolated: !isEditor }),
      },
    );
  };

  // In place when the gallery plays in place and this video can; otherwise the
  // lightbox (a poster-only item, or a link that is not a video).
  const openVideo = (index) => {
    if (playInline && inlineSource(videos?.[index]?.video)) {
      if (isEditor) setActiveIndex(index);
      startInline(index);
      return;
    }
    showLightbox(index);
  };

  const acceptConsent = () => {
    try {
      window.localStorage.setItem("vidgalblkVideoConsent", "1");
    } catch (error) {
      // Private browsing or storage disabled: consent still applies for the
      // rest of this page view via state, just isn't remembered afterward.
    }

    setConsentGranted(true);
    window.dispatchEvent(new Event("vidgalblkConsentGranted"));

    const index = pendingIndex;
    setPendingIndex(null);

    if (null !== index) {
      openVideo(index);
    }
  };

  const pendingVideo = null !== pendingIndex ? videos[pendingIndex] : null;

  const showFilter =
    false !== filter?.show && !!albums?.length && !!filter?.commonLabel;

  return (
    <>
      <Style
        attributes={attributes}
        id={id}
        isEditor={isEditor}
        galleryRef={galleryRef}
      />

      <div className={prefix}>
        {showFilter && (
          <VideoGalleryFilter
            attributes={attributes}
            id={id}
            activeAlbum={activeAlbum}
            setActiveAlbum={changeAlbum}
          />
        )}

        <div id={`${id}-gallery`} className="videoGallery" ref={galleryRef}>
          {revealedVideos.map(({ item, index }, position) => {
            const { video, poster, caption = "", albs } = item;
            const label = captionText(caption);
            const gated = consentGateEnabled && !consentGranted && needsConsent(video);
            const inlineSrc = playInline ? inlineSource(video) : null;
            const details = itemDetails(item, options, isEditor);

            if (inlineSrc && playingIndex === index) {
              return (
                <div
                  key={index}
                  data-item-key={String(index)}
                  className={`galleryItem vgbInlinePlaying ${albumClasses(albums, albs)}`}>
                  <InlinePlayer
                    source={inlineSrc}
                    title={label}
                    poster={poster || thumbs?.[index]}
                    isEditor={isEditor}
                  />
                  <button
                    type="button"
                    className="vgbInlineClose"
                    aria-label={__("Close video", "video-gallery-block")}
                    onClick={(e) => {
                      e.stopPropagation();
                      setPlayingIndex(null);
                    }}>
                    <svg viewBox="0 0 24 24" aria-hidden="true">
                      <path d="M18.3 5.7 12 12l6.3 6.3-1.4 1.4L10.6 13.4 4.3 19.7 2.9 18.3 9.2 12 2.9 5.7l1.4-1.4 6.3 6.3 6.3-6.3z" />
                    </svg>
                  </button>
                </div>
              );
            }

            return (
              <a
                key={index}
                data-item-key={String(index)}
                {...(isEditor
                  ? {
                      "data-editor-hint": previewOnClick
                        ? inlineSrc
                          ? __("Click to play", "video-gallery-block")
                          : __("Click to preview", "video-gallery-block")
                        : inlineSrc
                          ? __("Click to select · Double-click to play", "video-gallery-block")
                          : __("Click to select · Double-click to preview", "video-gallery-block"),
                    }
                  : {})}
                className={`galleryItem ${albumClasses(albums, albs)} ${
                  isEditor && index === activeIndex ? "bPlNowEditing" : ""
                }`}
                {...(gated || inlineSrc ? {} : { [LIGHTBOX_ATTR]: true })}
                {...(!gated && isFacebookVideo(video)
                  ? { "data-src": facebookEmbedUrl(video), "data-type": "iframe" }
                  : {})}
                {...(gated
                  ? {}
                  : {
                      /*
                       * The real video URL, for GA4 tracking: Fancybox
                       * rewrites YouTube/Vimeo URLs into its own player
                       * embed URL (full of its own query params) by the time
                       * `slide.src` is read at `Carousel.contentReady`, and
                       * the Facebook case above needs its embed iframe URL
                       * as `data-src` instead of the real one. This is the
                       * one place `pushVideoEvent()` can still get the
                       * original, clean URL from for a video opened via
                       * native `[data-vgb-lightbox]` binding rather than
                       * `showLightbox()`.
                       */
                      "data-video-url": video || poster,
                    })}
                href={video || poster}
                aria-label={
                  label ||
                  sprintf(
                    /* translators: %d: video number within the gallery. */
                    __("Play video %d", "video-gallery-block"),
                    index + 1,
                  )
                }
                onClick={(e) => {
                  if (gated) {
                    e.preventDefault();
                    e.stopPropagation();
                    setPendingIndex(index);
                    return;
                  }

                  if (!isEditor) {
                    // The lightbox opens itself through `data-vgb-lightbox`.
                    if (inlineSrc) {
                      e.preventDefault();
                      startInline(index);
                    }
                    return;
                  }
                  e.preventDefault();
                  e.stopPropagation();
                  if (previewOnClick) {
                    openVideo(index);
                    return;
                  }
                  setActiveIndex(index);
                }}
                onDoubleClick={(e) => {
                  // A single click has already opened it.
                  if (!isEditor || previewOnClick) return;
                  e.preventDefault();
                  e.stopPropagation();
                  openVideo(index);
                }}
                data-caption={sanitizeHTML(caption)}
                /*
                 * What Fancybox writes into an image slide's alt="". It reads
                 * this attribute's value back as plain text and puts it into
                 * the tag as it is, so it is escaped here, once. Without it
                 * Fancybox falls back to the caption, quotes and all, and a
                 * caption could close the attribute and add an onerror.
                 */
                data-alt={slideAlt(caption)}>
                <Thumbnail
                  video={video}
                  poster={poster}
                  thumb={thumbs?.[index]}
                  thumbSet={thumbSets?.[index]}
                  thumbSizes={thumbSizes}
                  caption={caption}
                />

                {details ? (
                  // "Show channel name" under the title; a tile without a
                  // channel keeps the caption it always had (render.php).
                  <div className="galleryItemCaption">
                    {options?.showCaptionOnThumbnail && caption && (
                      <span
                        className="galleryItemCaption__text"
                        dangerouslySetInnerHTML={{ __html: sanitizeHTML(caption) }}
                      />
                    )}
                    <span className="vgbItemDetails">{details}</span>
                  </div>
                ) : options?.showCaptionOnThumbnail && caption && (
                  <div
                    className="galleryItemCaption"
                    /*
                     * The caption is run through sanitizeHTML, which returns
                     * markup -- so it has to be set as markup. Rendering the
                     * returned string as a React child, which is what happened
                     * before, escaped it, and a caption with any formatting in
                     * it showed the visitor literal <b> tags.
                     */
                    dangerouslySetInnerHTML={{ __html: sanitizeHTML(caption) }}
                  />
                )}

                {false !== options?.showPlayIcon && (
                  <span className="playIcon" aria-hidden="true">
                    <svg viewBox="0 0 24 24">
                      <path d="M8 5v14l11-7z" />
                    </svg>
                  </span>
                )}

                {isEditor &&
                  renderTileTools &&
                  renderTileTools(
                    index,
                    revealedVideos[position - 1]?.index ?? -1,
                    revealedVideos[position + 1]?.index ?? -1,
                  )}
              </a>
            );
          })}
        </div>

        {hasMore && (
          <button
            type="button"
            className="vidgalblkLoadMore"
            onClick={() =>
              setVisibleCount((count) =>
                Math.min(count + perPage, visibleVideos.length),
              )
            }>
            {loadMoreLabel || __("Load More", "video-gallery-block")}
          </button>
        )}
      </div>

      {pendingVideo && (
        <div className="vidgalblkConsentGate" role="dialog" aria-modal="true">
          <div className="vidgalblkConsentGateBox">
            <p>
              {sprintf(
                /* translators: %s: video provider name, e.g. YouTube. */
                __(
                  "This video is hosted by %s. Playing it loads their player and shares data with them, in line with their privacy policy.",
                  "video-gallery-block",
                ),
                providerName(pendingVideo.video),
              )}
            </p>
            <div className="vidgalblkConsentGateActions">
              <button
                type="button"
                className="vidgalblkConsentGateAccept"
                onClick={acceptConsent}>
                {__("Play Video", "video-gallery-block")}
              </button>
              <button
                type="button"
                className="vidgalblkConsentGateCancel"
                onClick={() => setPendingIndex(null)}>
                {__("Cancel", "video-gallery-block")}
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

export default VideoGallery;
